Here's a `config.stash` version.
```python
@pytest.hookimpl(tryfirst=True)
def pytest_load_initial_conftests(early_config: Config) -> None:
    early_config.stash[key] = [str(p) for p in early_config.getini("pythonpath")]
    # `pythonpath = a b` will set `sys.path` to `[a, b, x, y, z, ...]`
    for path in reversed(early_config.stash[key]):
        sys.path.insert(0, path)


@pytest.hookimpl(trylast=True)
def pytest_unconfigure(config: Config) -> None:
    if key in config.stash:
        for path in config.stash[key]:
            sys.path.remove(path)
        del config.stash[key]
```

